def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the horizontal palette strip: adjacent rows repeat the same
    # run of nonzero colors.
    palette = None
    band_top = band_bottom = band_left = None
    for r in range(h - 1):
        for left in range(w):
            if grid[r][left] == 0:
                continue
            right = left
            while right < w and grid[r][right] != 0:
                right += 1
            seq = grid[r][left:right]
            if len(seq) < 2:
                continue
            bottom = r + 1
            while bottom < h and grid[bottom][left:right] == seq:
                bottom += 1
            if bottom - r >= 2:
                palette = seq
                band_top, band_bottom, band_left = r, bottom, left
                break
        if palette is not None:
            break

    if palette is None:
        return [row[:] for row in grid]

    band_cells = {
        (r, c)
        for r in range(band_top, band_bottom)
        for c in range(band_left, band_left + len(palette))
    }

    # Extract the non-strip component matching a palette color; this is the
    # template shape.
    components = []
    visited = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if not color or color not in palette or (r, c) in band_cells or (r, c) in visited:
                continue
            todo = [(r, c)]
            visited.add((r, c))
            comp = []
            while todo:
                y, x = todo.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if (0 <= yy < h and 0 <= xx < w and
                        (yy, xx) not in band_cells and (yy, xx) not in visited and
                        grid[yy][xx] == color):
                        visited.add((yy, xx))
                        todo.append((yy, xx))
            components.append((len(comp), color, comp))

    _, template_color, template = max(components, key=lambda x: x[0])
    top = min(r for r, c in template)
    left = min(c for r, c in template)
    shape = [(r - top, c - left) for r, c in template]
    shape_height = max(dr for dr, dc in shape) + 1
    first_top = top - palette.index(template_color) * shape_height

    result = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        for dr, dc in shape:
            rr = first_top + i * shape_height + dr
            cc = left + dc
            if 0 <= rr < h and 0 <= cc < w:
                result[rr][cc] = color
    return result
